const { user_id, session_id, confirm } = $('TOOL - Start').first().json;
const { confirmable } = $input.first().json;

if (confirm !== true || confirmable !== true) {
  return [{
    json: {
      ok: false,
      message: "Suppression non effectuée : la confirmation doit arriver dans un message séparé, après avoir prévenu l'utilisateur. Explique-lui que cette action efface définitivement son compte, ses réglages et son historique, et demande-lui de confirmer dans son prochain message."
    }
  }];
}

return [{ json: { ok: true, user_id, session_id } }];

const r = $input.first().json;

if (!r.id) {
  return [{ json: { ok: false, message: "Aucun compte à supprimer." } }];
}

return [{
  json: {
    ok: true,
    message: "Toutes les données de l'utilisateur ont été supprimées : compte, réglages, sessions, historique de conversation et historique d'envoi. Il est maintenant déconnecté."
  }
}];

parameters.query:
WITH prev AS (
  SELECT exec_id <> $2 AND requested_at > NOW() - INTERVAL '10 minutes' AS confirmable
  FROM delete_requests WHERE session_id = $1
), save AS (
  INSERT INTO delete_requests (session_id, exec_id, requested_at)
  SELECT $1, $2, NOW()
  WHERE NOT ($3::boolean AND COALESCE((SELECT confirmable FROM prev), false))
  ON CONFLICT (session_id) DO UPDATE SET exec_id = EXCLUDED.exec_id, requested_at = EXCLUDED.requested_at
)
SELECT COALESCE((SELECT confirmable FROM prev), false) AS confirmable;
